import time
class Solution:
    def sumGame(self, num: str) -> bool:
        n = len(num)
        num1 = list(num[:n // 2])
        num2 = list(num[n // 2:])

        n1 = num1.count('?')
        n2 = num2.count('?')
        if n1 == n2:
            while '?' in num1:
                num1.remove('?')
            while '?' in num2:
                num2.remove('?')
            return not (sum([int(x) for x in num1]) == sum([int(x) for x in num2]))

        if n1 < n2:
            base = num1
            other = num2
        else:
            base = num2
            other = num1

        minn=min(n1,n2)
        maxn=max(n1,n2)

        if (maxn-minn)%2 == 1:
            return True

        eachtime = (maxn-minn) // 2
        sum_base = sum([int(x) for x in base if x!='?'])
        sum_other = sum([int(x) for x in other if x != '?'])

        if sum_base - sum_other == eachtime * 9:
            return False

        return True


